#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int minCut(const char*s){
 int n=(int)strlen(s); unsigned char*p=calloc((size_t)n*n,1); int*dp=malloc(n*sizeof(int));
 for(int r=0;r<n;r++){dp[r]=r;
  for(int l=0;l<=r;l++) if(s[l]==s[r]&&(r-l<2||p[(size_t)(l+1)*n+r-1])){
   p[(size_t)l*n+r]=1; dp[r]=(l==0)?0:(dp[r]<dp[l-1]+1?dp[r]:dp[l-1]+1);
  }
 }
 int a=dp[n-1]; free(p); free(dp); return a;
}

