class Solution {
    public int minCut(String s) {
        int n=s.length(); boolean[][] p=new boolean[n][n]; int[] dp=new int[n];
        for(int r=0;r<n;r++){ dp[r]=r;
            for(int l=0;l<=r;l++) if(s.charAt(l)==s.charAt(r)&&(r-l<2||p[l+1][r-1])){
                p[l][r]=true; dp[r]=(l==0)?0:Math.min(dp[r],dp[l-1]+1);
            }
        }
        return dp[n-1];
    }
}

